<?php
declare(strict_types=1);
final class StaySchema
{
    private static function bad():never{throw new HttpError(400,'Kiểm tra thông tin cơ sở, loại phòng và lịch giá.');}
    private static function keys(array $v,array $allowed):void{if(array_diff(array_keys($v),$allowed)||in_array(null,$v,true))self::bad();}
    private static function integer(mixed $v,int $min,int $max):int{if(!is_int($v)||$v<$min||$v>$max)self::bad();return $v;}
    private static function bool(mixed $v):bool{if(!is_bool($v))self::bad();return $v;}
    private static function text(mixed $v,int $max,int $min=0):string{if(!is_string($v)||str_contains($v,"\0"))self::bad();$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);if($v===null)self::bad();$n=strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2;if($n<$min||$n>$max)self::bad();return $v;}
    private static function uuid(mixed $v):string{if(!is_string($v)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$v))self::bad();return strtolower($v);}
    public static function date(mixed $v):string{if(!is_string($v)||!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$v,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))self::bad();return $v;}
    private static function array(mixed $v,int $max):array{if(!is_array($v)||!array_is_list($v)||count($v)>$max)self::bad();return $v;}
    private static function discount(mixed $v):array{if(!is_array($v))self::bad();self::keys($v,['type','value']);if(!in_array($v['type'] ?? '',['NONE','PERCENT','FIXED'],true))self::bad();return ['type'=>$v['type'],'value'=>self::integer($v['value'] ?? null,0,$v['type']==='PERCENT'?100:100000000)];}
    private static function rate(mixed $r):array
    {
        if(!is_array($r))self::bad();self::keys($r,['id','from','to','weekdays','price','stock','closed','discount','priority','note']);$out=['id'=>self::uuid($r['id'] ?? null),'from'=>self::date($r['from'] ?? null),'to'=>self::date($r['to'] ?? null),'weekdays'=>self::array($r['weekdays'] ?? [],7)];if($out['from']>$out['to']||count(array_unique($out['weekdays'],SORT_REGULAR))!==count($out['weekdays']))self::bad();foreach($out['weekdays'] as $day)self::integer($day,0,6);foreach(['price'=>100000000,'stock'=>1000] as $key=>$max)if(array_key_exists($key,$r))$out[$key]=self::integer($r[$key],0,$max);if(array_key_exists('closed',$r))$out['closed']=self::bool($r['closed']);if(array_key_exists('discount',$r))$out['discount']=self::discount($r['discount']);if(!array_intersect(['price','stock','closed','discount'],array_keys($r)))self::bad();$out['priority']=self::integer($r['priority'] ?? 10,0,1000);$out['note']=self::text($r['note'] ?? '',300);return $out;
    }
    private static function room(mixed $r):array
    {
        if(!is_array($r))self::bad();self::keys($r,['id','name','nameEn','description','descriptionEn','imageId','beds','bedsEn','maxGuests','maxAdults','maxChildren','price','stock','active','saleFrom','saleTo','discount','rates']);$out=['id'=>self::uuid($r['id'] ?? null),'name'=>self::text($r['name'] ?? null,150,1)];foreach(['nameEn'=>150,'description'=>2000,'descriptionEn'=>2000,'beds'=>150,'bedsEn'=>150] as $key=>$max)$out[$key]=self::text($r[$key] ?? '',$max);if(array_key_exists('imageId',$r))$out['imageId']=self::uuid($r['imageId']);foreach(['maxGuests'=>[1,30],'maxAdults'=>[1,30],'maxChildren'=>[0,20],'price'=>[1,100000000],'stock'=>[0,1000]] as $key=>[$min,$max])$out[$key]=self::integer($r[$key] ?? null,$min,$max);if($out['maxAdults']>$out['maxGuests']||$out['maxChildren']>$out['maxGuests'])self::bad();$out['active']=self::bool($r['active'] ?? null);foreach(['saleFrom','saleTo'] as $key)if(array_key_exists($key,$r))$out[$key]=self::date($r[$key]);if(isset($out['saleFrom'],$out['saleTo'])&&$out['saleFrom']>$out['saleTo'])self::bad();$out['discount']=self::discount($r['discount'] ?? ['type'=>'NONE','value'=>0]);$out['rates']=array_map(self::rate(...),self::array($r['rates'] ?? [],500));if(count(array_unique(array_column($out['rates'],'id')))!==count($out['rates']))self::bad();return $out;
    }
    public static function property(array $p):array
    {
        self::keys($p,['id','version','slug','slugEn','name','nameEn','description','descriptionEn','destination','destinationEn','address','addressEn','mapUrl','coverId','galleryIds','amenities','amenitiesEn','policy','policyEn','checkInTime','checkOutTime','minNights','maxNights','status','sortOrder','rooms']);$out=['id'=>self::uuid($p['id'] ?? null),'version'=>self::integer($p['version'] ?? null,0,2147483646)];foreach(['slug'=>false,'slugEn'=>true] as $key=>$optional){$v=self::text($p[$key] ?? ($optional?'':null),150);if(!($optional&&$v==='')&&!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/D',$v)||in_array($v,['tra-cuu','booking'],true))self::bad();$out[$key]=$v;}foreach(['name'=>[180,1],'nameEn'=>[180,0],'description'=>[15000,0],'descriptionEn'=>[15000,0],'destination'=>[150,1],'destinationEn'=>[150,0],'address'=>[500,3],'addressEn'=>[500,0],'amenities'=>[3000,0],'amenitiesEn'=>[3000,0],'policy'=>[8000,0],'policyEn'=>[8000,0]] as $key=>[$max,$min])$out[$key]=self::text($p[$key] ?? ($min?null:''),$max,$min);$out['mapUrl']=self::text($p['mapUrl'] ?? '',8000);if($out['mapUrl']!==''&&(!filter_var($out['mapUrl'],FILTER_VALIDATE_URL)||!str_starts_with($out['mapUrl'],'https://')))self::bad();if(array_key_exists('coverId',$p))$out['coverId']=self::uuid($p['coverId']);$out['galleryIds']=array_map(self::uuid(...),self::array($p['galleryIds'] ?? [],20));foreach(['checkInTime'=>'14:00','checkOutTime'=>'12:00'] as $key=>$default){$v=$p[$key] ?? $default;if(!is_string($v)||!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/D',$v))self::bad();$out[$key]=$v;}$out['minNights']=self::integer($p['minNights'] ?? 1,1,30);$out['maxNights']=self::integer($p['maxNights'] ?? 30,1,30);if($out['minNights']>$out['maxNights']||!in_array($p['status'] ?? '',['DRAFT','PUBLISHED','ARCHIVED'],true))self::bad();$out['status']=$p['status'];$out['sortOrder']=self::integer($p['sortOrder'] ?? 100,0,10000);$out['rooms']=array_map(self::room(...),self::array($p['rooms'] ?? null,30));if(count(array_unique(array_column($out['rooms'],'id')))!==count($out['rooms'])||$out['status']==='PUBLISHED'&&!array_filter($out['rooms'],fn($r)=>$r['active']))self::bad();return $out;
    }
    private static function rules(array $room,string $date):array
    {
        $rules=[];$weekday=(int)(new DateTimeImmutable($date,new DateTimeZone('UTC')))->format('w');foreach($room['rates'] as $i=>$r)if($r['from']<=$date&&$r['to']>=$date&&(!$r['weekdays']||in_array($weekday,$r['weekdays'],true)))$rules[]=$r+['index'=>$i];usort($rules,fn($a,$b)=>$b['priority']<=>$a['priority']?:((strtotime($a['to'].'T00:00:00Z')-strtotime($a['from'].'T00:00:00Z'))<=>(strtotime($b['to'].'T00:00:00Z')-strtotime($b['from'].'T00:00:00Z')))?:$b['index']<=>$a['index']);return $rules;
    }
    public static function stock(array $room,string $date):int
    {
        foreach(self::rules($room,$date) as $r)if(array_key_exists('stock',$r))return $r['stock'];return $room['stock'];
    }
    public static function night(array $room,string $date):array
    {
        self::date($date);if(isset($room['saleFrom'])&&$date<$room['saleFrom']||isset($room['saleTo'])&&$date>$room['saleTo'])throw new HttpError(400,'Loại phòng chưa có giá cho đêm '.$date.'.');$values=['closed'=>false,'price'=>$room['price'],'stock'=>$room['stock'],'discount'=>$room['discount']];$rules=self::rules($room,$date);foreach($values as $key=>&$v)foreach($rules as $r)if(array_key_exists($key,$r)){$v=$r[$key];break;}unset($v);$d=$values['discount'];$reduction=$d['type']==='PERCENT'?intdiv($values['price']*$d['value'],100):($d['type']==='FIXED'?min($values['price'],$d['value']):0);return ['date'=>$date,'closed'=>$values['closed'],'price'=>$values['price'],'stock'=>$values['stock'],'discount'=>$reduction,'unitPrice'=>$values['price']-$reduction];
    }
}
